:root{--navy:#17385b;--edge:#dee6eb;--teal:#007c86}*{box-sizing:border-box}body{margin:0;background:#f4f8fa;color:#243746;font:15px/1.5 system-ui,Arial,sans-serif}.shell{display:grid;grid-template-columns:240px 1fr;min-height:100vh}.nav{background:#163455;color:white;padding:30px 18px}.nav h2{margin:0 0 12px;font-size:23px}.nav a,.nav button{display:block;width:100%;padding:12px;color:#edf7ff;text-align:left;background:none;border:0;text-decoration:none;border-radius:8px;cursor:pointer}.nav a:hover,.nav button:hover{background:#315876}.content{padding:28px;max-width:1550px;width:100%;margin:auto}.top{display:flex;justify-content:space-between;align-items:center;gap:14px;flex-wrap:wrap}.subtitle{color:#667788}.tiles{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:16px;margin:20px 0}.tile,.panel{background:white;border:1px solid var(--edge);border-radius:14px;padding:18px;box-shadow:0 3px 15px #2334440b}.tile strong{display:block;font-size:27px;color:var(--navy)}h1{margin:0;font-size:26px}h2{font-size:20px;margin:0 0 14px}.section{display:none}.section.active{display:block}.controls{display:flex;align-items:center;gap:10px;flex-wrap:wrap;margin-bottom:15px}input,select,textarea{font:inherit;padding:10px;border:1px solid #cbd7df;border-radius:8px;max-width:100%;background:white}textarea{min-height:95px}button{font:inherit;cursor:pointer}.btn{background:var(--teal);color:white;border:0;border-radius:8px;padding:10px 16px}.btn.secondary{background:#526b7c}.btn.warn{background:#9e4141}.btn:disabled{opacity:.45;cursor:not-allowed}.scroll{overflow-x:auto}table{border-collapse:collapse;width:100%;min-width:650px}th,td{padding:12px;text-align:left;border-bottom:1px solid #e7edf1}th{background:#f6f9fb;color:#50616b;font-size:13px}td .btn{padding:6px 10px;font-size:12px}.muted{color:#6a7a85}.forms{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}label{display:grid;gap:5px;font-weight:600;font-size:13px}label input,label select,label textarea{width:100%}.span{grid-column:1/-1}.notice{padding:12px;border-radius:8px;background:#e9f5f6;margin:12px 0;display:none}.notice.error{background:#fff0ed;color:#8a2424}.modal{position:fixed;inset:0;background:#182d3c99;display:none;align-items:center;justify-content:center;z-index:60;padding:18px}.modal.open{display:flex}.modal>div{background:white;border-radius:15px;padding:24px;max-height:80vh;overflow-y:auto;width:min(690px,100%)}.modal-head{display:flex;justify-content:space-between;gap:10px}.close{border:0;background:none;font-size:25px}.tiny{font-size:12px}.hidden{display:none!important}@media(max-width:900px){.shell{grid-template-columns:1fr}.nav{padding:14px;display:flex;gap:5px;flex-wrap:wrap}.nav h2{width:100%}.nav a,.nav button{width:auto}.tiles{grid-template-columns:repeat(2,1fr)}.content{padding:14px}}@media(max-width:560px){.tiles,.forms{grid-template-columns:1fr}.tile strong{font-size:23px}}
