@if($role === 'admin')<div id="paymentModal" class="modal"><div><div class="modal-head"><h2>Record Payment</h2><button class="close" onclick="closeModal('paymentModal')">×</button></div><form id="paymentForm" class="forms"><label class="span">Completed appointment<select name="appointment_id" required>@foreach($appointments->where('status','Completed') as $a)<option value="{{ $a->id }}">#{{ $a->id }} — {{ $a->guest_name }} — {{ $a->service?->name }}</option>@endforeach</select></label><label>Amount (PHP)<input type="number" name="amount" step="0.01" min="0.01" required></label><label>Payment method<select name="payment_method"><option>Cash</option><option>GCash</option><option>Maya</option><option>Card</option><option>Bank Transfer</option></select></label><button class="btn">Save payment</button></form></div></div>@endif
<script>
const csrf=document.querySelector('meta[name="csrf-token"]').content;
const role=@json($role);let appointmentID=null,verificationID=null;
function showMessage(message,error=false){const n=document.getElementById('notice');n.textContent=message;n.classList.toggle('error',error);n.style.display='block';window.scrollTo({top:0,behavior:'smooth'})}
async function request(url,method='GET',body=null){const r=await fetch(url,{method,credentials:'same-origin',headers:{'Accept':'application/json','Content-Type':'application/json','X-CSRF-TOKEN':csrf},body:body?JSON.stringify(body):null});const data=await r.json().catch(()=>({}));if(!r.ok)throw Error(data.message||Object.values(data.errors||{}).flat().join(' ')||'Request failed');return data}
function act(promise,success='Saved'){promise.then(()=>{showMessage(success);setTimeout(()=>location.reload(),600)}).catch(e=>showMessage(e.message,true))}
function openModal(id){document.getElementById(id)?.classList.add('open')}function closeModal(id){document.getElementById(id)?.classList.remove('open')}
function filterRows(input,id){const q=input.value.trim().toLowerCase();document.querySelectorAll('#'+id+' tr').forEach(tr=>{const matches=!q||tr.textContent.toLowerCase().includes(q);tr.dataset.searchHidden=matches?'false':'true';tr.hidden=!matches;});window.CerilloPagination?.refreshTable(input.closest('.section')?.querySelector('table'),true)}
function changeTab(){const k=location.hash.slice(1)||'dashboard';document.querySelectorAll('.section').forEach(s=>s.classList.toggle('active',s.id===k));if(!document.getElementById(k))document.getElementById('dashboard').classList.add('active')};window.addEventListener('hashchange',changeTab);changeTab();
document.getElementById('blockForm')?.addEventListener('submit',e=>{e.preventDefault();const v=Object.fromEntries(new FormData(e.target));act(request('/api/blocks','POST',v),'Block created')});
function deleteBlock(id){if(confirm('Remove this unavailable period?'))act(request('/api/blocks/'+id,'DELETE'),'Block removed')}
function setStatus(id,status){act(request('/api/appointments/'+id+'/status','PATCH',{status}),'Appointment updated')}
function cancelBooking(id){const reason=prompt('Reason for cancellation:');if(reason?.trim())act(request('/api/appointments/'+id+'/status','PATCH',{status:'Cancelled',cancellation_reason:reason.trim()}),'Appointment cancelled')}
async function verifyBooking(id){verificationID=id;try{const matches=await request('/api/appointments/'+id+'/matches');const select=document.getElementById('matchingPatient');select.replaceChildren(new Option('No existing patient — verified guest',''));matches.forEach(p=>select.add(new Option(`${p.name} — ${p.formatted_phone || window.CerilloFormat?.phone(p.phone) || p.phone || '—'}`,p.id)));openModal('verifyModal')}catch(e){showMessage(e.message,true)}}
function confirmVerify(){act(request('/api/appointments/'+verificationID+'/verify','POST',{patient_id:document.getElementById('matchingPatient').value||null}),'Booking verified')}
function clinicalEdit(id){appointmentID=id;openModal('clinicalModal')}
function saveNotes(){const v=document.getElementById('treatmentNotes').value.trim();if(!v)return showMessage('Treatment notes are required.',true);request('/api/appointments/'+appointmentID+'/clinical','PUT',{treatment_notes:v}).then(()=>showMessage('Clinical notes saved')).catch(e=>showMessage(e.message,true))}
function saveTooth(){const c=document.getElementById('toothCondition').value.trim();if(!c)return showMessage('Enter a tooth condition.',true);request('/api/appointments/'+appointmentID+'/teeth','POST',{tooth_id:document.getElementById('toothID').value,condition:c,notes:document.getElementById('toothNotes').value}).then(()=>showMessage('Tooth entry saved')).catch(e=>showMessage(e.message,true))}
function completeAppointment(){if(!confirm('Finalize this appointment and its clinical record?'))return;act(request('/api/appointments/'+appointmentID+'/complete','POST',{}),'Appointment completed; patient record linked')}
async function viewChart(id){try{const data=await request('/api/patients/'+id+'/chart');const holder=document.getElementById('chartContent');holder.replaceChildren();const title=document.createElement('p');title.textContent=data.patient.name+' — '+(data.patient.formatted_patient_code || window.CerilloFormat?.patientCode(data.patient.patient_code, data.patient.id) || data.patient.patient_code);holder.append(title);const entries=data.history.data||[];if(!entries.length){holder.append(document.createTextNode('No findings recorded yet.'))}else{entries.forEach(e=>{const p=document.createElement('p');const tooth=data.teeth.find(t=>t.id===e.tooth_id);p.textContent=`Tooth ${tooth?.fdi_number||e.tooth_id}: ${e.condition} — ${e.notes||''}`;holder.append(p)})}openModal('chartModal')}catch(e){showMessage(e.message,true)}}
@if($role !== 'dentist')
document.getElementById('patientSelect')?.addEventListener('change',e=>{const x=e.target.selectedOptions[0];if(e.target.value){document.getElementById('guestName').value=x.dataset.name||'';document.getElementById('guestPhone').value=window.CerilloFormat?.normalizePhone(x.dataset.phone)||x.dataset.phone||'';document.getElementById('guestEmail').value=x.dataset.email||''}});
async function loadSlots(){const d=document.getElementById('bookDate').value,dent=document.getElementById('bookDentist').value,service=document.getElementById('bookService').value,s=document.getElementById('bookSlot');s.replaceChildren(new Option('Select available time',''));if(!d||!dent||!service)return;try{const rows=await request(`/api/slots?dentist_id=${encodeURIComponent(dent)}&service_id=${encodeURIComponent(service)}&date=${encodeURIComponent(d)}`);rows.forEach(v=>{const option=new Option(v.starts_at.slice(11,16)+(v.available?'':' — unavailable'),v.starts_at);option.disabled=!v.available;s.add(option)})}catch(e){showMessage(e.message,true)}}
['bookDate','bookDentist','bookService'].forEach(id=>document.getElementById(id)?.addEventListener('change',loadSlots));
document.getElementById('bookForm')?.addEventListener('submit',e=>{e.preventDefault();const f=e.target,values=Object.fromEntries(new FormData(f));values.starts_at=document.getElementById('bookSlot').value;if(!values.starts_at)return showMessage('Choose an available time.',true);if(!confirm(`Book ${values.guest_name} on ${values.starts_at}?`))return;values.patient_id=values.patient_id||null;act(request('/api/appointments','POST',values),'Appointment booked')});
@endif
@if($role === 'admin')
document.getElementById('serviceForm')?.addEventListener('submit',e=>{e.preventDefault();const v=Object.fromEntries(new FormData(e.target));v.active=v.active==='1';act(request('/api/services','POST',v),'Service created')});
function editService(id,name,price,duration,active){const n=prompt('Service name',name);if(n===null)return;const p=prompt('Price',price);if(p===null)return;const d=prompt('Duration (minutes)',duration);if(d===null)return;act(request('/api/services/'+id,'PUT',{name:n,price:p,duration_minutes:d,active}),'Service updated')}
function deleteService(id){if(confirm('Delete this service? Services used in appointments cannot be deleted.'))act(request('/api/services/'+id,'DELETE'),'Service deleted')}
function voidPayment(id){const reason=prompt('Reason for voiding this payment:');if(reason?.trim())act(request('/api/transactions/'+id+'/void','POST',{void_reason:reason.trim()}),'Payment voided')}
document.getElementById('paymentForm')?.addEventListener('submit',e=>{e.preventDefault();act(request('/api/transactions','POST',Object.fromEntries(new FormData(e.target))),'Payment recorded')});
@endif
</script>
<script src="/assets/js/cerillo-responsive.js"></script>
<script src="/assets/js/cerillo-table-pagination.js"></script>
</body></html>
